// Property-based tests for the domain layer.
//
// These live in a separate binary to avoid a process-exit deadlock between
// proptest's thread-pool and #[tokio::test(flavor = "multi_thread")] runtimes
// that coexist in the main unit-test binary (see CLAUDE.md §"Proptest Isolation").

use std::collections::HashMap;

// The shared integration-test helpers (`test_config`, `metrics_scrape_only`,
// the `upload_stream` seam);
// the module silences dead code for the items a binary leaves unused.
#[path = "common/mod.rs"]
mod common;

use bytes::Bytes;
use proptest::prelude::*;
use proptest::test_runner::Config as ProptestConfig;

use live_edit::checkpoint::{
    decode_tail_envelope, encode_tail_envelope, peek_tail_header, TailHeader, TailRecord,
    TailRecordKind, TAIL_FORMAT_VERSION, TAIL_HEADER_SIZE, TAIL_MAX_SEQUENCE,
};
use live_edit::domain::delta::{apply_delta, DeltaError, StorageMutation};
use live_edit::domain::ompf::OmpfContainer;
use live_edit::domain::types::ObjectState;
use live_edit::storage::diff_read::snapshot_to_object_state;
use oodf_ffi::{
    CommandCreateSection, CommandDeleteSection, OwnedDelta, SetField, StructCommand,
    TimeSample as OodfTimeSample,
};

/// Build a `ProptestConfig` with `cases = default_cases`, overridden by the
/// `PROPTEST_CASES` environment variable when set (a manual knob; CI runs the
/// defaults — see CLAUDE.md `### Proptest Isolation`). Pre-helper the
/// per-block hardcoded `cases: 256` made every override a silent no-op.
/// Raising it well above the default exhausts local ports in the
/// Valkey-backed blocks: at 1000, three parity blocks fail with
/// `AddrNotAvailable` on connect even with `proptest_config_with_cap`.
///
/// `failure_persistence: None` is set unconditionally so proptest does not
/// attempt to write counterexamples under `proptest-regressions/`. Test runs
/// in containerized CI have a read-only workspace; the warn-on-write would
/// surface as a noisy startup log even though it doesn't fail the run.
fn proptest_config(default_cases: u32) -> ProptestConfig {
    let cases = std::env::var("PROPTEST_CASES")
        .ok()
        .and_then(|s| s.parse::<u32>().ok())
        .unwrap_or(default_cases);
    ProptestConfig {
        cases,
        failure_persistence: None,
        ..ProptestConfig::default()
    }
}

/// Variant of `proptest_config` that respects `PROPTEST_CASES` but clamps
/// the resulting case count to `max_override`. Used by Valkey-backed
/// proptest blocks where each case spins up two fresh TestValkey fixtures
/// (~80 ms of fred-connect time per fixture); under `PROPTEST_CASES=1000`
/// an uncapped 32-case default scales to 1000 × 2 × 80 ms ≈ 160 s of
/// fred-connect time *per block* — overwhelming test wall time without
/// adding meaningful coverage. The cap keeps the block under a fixed
/// upper bound (default 64 cases for the b.k1r / b.qw6 parity blocks)
/// regardless of the env override. Pure-logic proptest blocks continue
/// to use the uncapped `proptest_config` helper so they DO scale up
/// under `PROPTEST_CASES=1000`.
fn proptest_config_with_cap(default_cases: u32, max_override: u32) -> ProptestConfig {
    let env_or_default = std::env::var("PROPTEST_CASES")
        .ok()
        .and_then(|s| s.parse::<u32>().ok())
        .unwrap_or(default_cases);
    let cases = env_or_default.min(max_override);
    ProptestConfig {
        cases,
        failure_persistence: None,
        ..ProptestConfig::default()
    }
}

// ── Shared test helpers ──────────────────────────────────────────────────────

fn make_state() -> ObjectState {
    ObjectState {
        object_id: 1,
        ..Default::default()
    }
}

// ── Delta proptest infrastructure ────────────────────────────────────────────

#[derive(Debug, Clone)]
enum PropCmd {
    CreateSection {
        parent_id: u64,
        section_id: u64,
        name: String,
    },
    DeleteSection {
        section_id: u64,
    },
    SetField {
        section_id: u64,
        key: String,
        value: u8,
        /// Raw per-delta authoring rank emitted on the wire. Varied (and
        /// bounded well under `MAX_DELTA_SET_ORDER`) so the persisted
        /// `Field::authoring_set_order` invariant is exercised across a
        /// broad, cursor-independent value space rather than the constant
        /// `0` the pre-`t3.msb.35.ey.r7` generator emitted.
        set_order: u64,
    },
}

/// Per-delta authoring `set_order` upper bound for the generated `SetField`
/// strategy. Chosen so that summing across the (≤ 20)-delta sequence can
/// never advance the running `next_set_order` cursor past the 2^53 − 1
/// `SET_ORDER_CEILING` (which would surface as `DeltaError::SetOrderOverflow`,
/// an error the tolerant apply helper does not roll back). With ≤ 20 deltas
/// the worst-case cursor is bounded by `20 × MAX + 20`; `2^40` keeps that
/// comfortably under `2^53 − 1` while still spanning a wide, clearly
/// cursor-independent value space. `MAX_DELTA_SET_ORDER` (`2^53 − 1`) is the
/// validator ceiling this stays strictly below.
const SAFE_AUTHORING_SET_ORDER_MAX: u64 = 1 << 40;
const _: () =
    assert!(SAFE_AUTHORING_SET_ORDER_MAX < live_edit::domain::limits::MAX_DELTA_SET_ORDER);

fn arb_section_id() -> impl Strategy<Value = u64> {
    1u64..=20u64
}

fn arb_section_name() -> impl Strategy<Value = String> {
    "[a-z]{1,4}"
}

fn arb_prop_cmd() -> impl Strategy<Value = PropCmd> {
    prop_oneof![
        // b.39x medium: drop self-parenting tuples — `apply_delta` now
        // rejects `parent_id == section_id` (with `parent_id != 0`) at
        // validation time as a `DeltaError::SelfParenting`. The proptest
        // contract expects valid inputs to succeed, so the strategy
        // narrows to the well-formed subset rather than asserting on the
        // rejection path.
        (0u64..=5u64, arb_section_id(), arb_section_name())
            .prop_filter(
                "self-parenting CreateSection rejected by b.39x validator",
                |(parent, sid, _name)| { *parent == 0 || parent != sid }
            )
            .prop_map(|(parent, sid, name)| {
                PropCmd::CreateSection {
                    parent_id: parent,
                    section_id: sid,
                    name,
                }
            }),
        arb_section_id().prop_map(|sid| PropCmd::DeleteSection { section_id: sid }),
        (
            arb_section_id(),
            "[a-z]{1,3}",
            any::<u8>(),
            0u64..=SAFE_AUTHORING_SET_ORDER_MAX,
        )
            .prop_map(|(sid, key, val, so)| PropCmd::SetField {
                section_id: sid,
                key,
                value: val,
                set_order: so,
            }),
    ]
}

fn arb_cmd_sequence() -> impl Strategy<Value = Vec<PropCmd>> {
    prop::collection::vec(arb_prop_cmd(), 1..=20)
}

fn cmd_to_delta(cmd: &PropCmd) -> OwnedDelta {
    match cmd {
        PropCmd::CreateSection {
            parent_id,
            section_id,
            name,
        } => OwnedDelta {
            is_diff: false,
            struct_commands: vec![StructCommand::CreateSection(CommandCreateSection {
                parent_id: *parent_id,
                section_id: *section_id,
                section_name: name.clone(),
                section_type: 0,
            })],
            ..Default::default()
        },
        PropCmd::DeleteSection { section_id } => OwnedDelta {
            is_diff: false,
            struct_commands: vec![StructCommand::DeleteSection(CommandDeleteSection {
                parent_id: 0,
                section_id: *section_id,
            })],
            ..Default::default()
        },
        PropCmd::SetField {
            section_id,
            key,
            value,
            set_order,
        } => OwnedDelta {
            is_diff: false,
            set_fields: vec![SetField {
                section_id: *section_id,
                key_name: key.clone(),
                value_or_ext_hash: vec![*value],
                ext_value_size: 0,
                ext_value_index: 0,
                set_order: *set_order,
            }],
            ..Default::default()
        },
    }
}

/// Apply a delta, tolerating protocol-violation errors that the random
/// generator can produce but the engine now rejects (e.g. `DuplicateSection`
/// from a re-used `section_id` — b.y2t). On rejection `state` is rolled back
/// to its pre-call value to mirror the production caller that abandons the
/// transaction on error.
///
/// Returns `Ok(Some(mutations))` on success, `Ok(None)` on a tolerated
/// rejection, or `Err(e)` for any other error (which should never happen for
/// generator-produced deltas).
fn apply_delta_tolerant(
    state: &mut ObjectState,
    delta: OwnedDelta,
) -> Result<Option<Vec<StorageMutation>>, DeltaError> {
    let snapshot = state.clone();
    match apply_delta(state, Some(delta)) {
        Ok(m) => Ok(Some(m)),
        Err(DeltaError::DuplicateSection { .. }) => {
            *state = snapshot;
            Ok(None)
        }
        Err(e) => Err(e),
    }
}

fn apply_prop_cmds(state: &mut ObjectState, cmds: &[PropCmd]) {
    for cmd in cmds {
        apply_delta_tolerant(state, cmd_to_delta(cmd))
            .expect("apply_delta must not error on valid delta");
    }
}

// ── Delta property-based tests (SDD §19.4) ──────────────────────────────────

proptest! {
    #![proptest_config(proptest_config(256))]

    #[test]
    fn proptest_same_command_sequence_produces_deterministic_state(
        cmds in arb_cmd_sequence(),
    ) {
        let mut state_a = make_state();
        let mut state_b = make_state();
        apply_prop_cmds(&mut state_a, &cmds);
        apply_prop_cmds(&mut state_b, &cmds);
        prop_assert_eq!(
            state_a.sequence_num, state_b.sequence_num,
            "sequence_num must match after identical command sequence"
        );
        prop_assert_eq!(
            state_a.sections.len(), state_b.sections.len(),
            "section count must match after identical command sequence"
        );
        prop_assert_eq!(
            state_a.fields.len(), state_b.fields.len(),
            "field count must match after identical command sequence"
        );
    }
}

proptest! {
    #![proptest_config(proptest_config(256))]

    #[test]
    fn proptest_sequence_num_strictly_increases_per_delta(
        cmds in arb_cmd_sequence(),
    ) {
        let mut state = make_state();
        let mut prev_seq = state.sequence_num;
        for cmd in &cmds {
            // Rejected deltas leave state untouched (rolled back by the
            // tolerant helper); skip the invariant check on those.
            if apply_delta_tolerant(&mut state, cmd_to_delta(cmd)).unwrap().is_none() {
                continue;
            }
            prop_assert!(
                state.sequence_num == prev_seq + 1,
                "sequence_num must increment by exactly 1 per delta; was {} now {}",
                prev_seq, state.sequence_num
            );
            prev_seq = state.sequence_num;
        }
    }
}

proptest! {
    #![proptest_config(proptest_config(256))]

    #[test]
    fn proptest_next_set_order_never_decreases(
        cmds in arb_cmd_sequence(),
    ) {
        let mut state = make_state();
        let mut prev_nso = state.next_set_order;
        for cmd in &cmds {
            apply_delta_tolerant(&mut state, cmd_to_delta(cmd)).unwrap();
            prop_assert!(
                state.next_set_order >= prev_nso,
                "nextSetOrder must never decrease; was {} now {}",
                prev_nso, state.next_set_order
            );
            prev_nso = state.next_set_order;
        }
    }
}

proptest! {
    #![proptest_config(proptest_config(256))]

    /// t3.msb.35.ey.r7 — persisted authoring `set_order` equals the writing
    /// delta's `set_order`, across arbitrary sequences.
    ///
    /// Task 1's `Field::authoring_set_order` captures the *raw* per-delta
    /// authoring rank of the last LWW-winning write to a `(section_id,
    /// key_name)` — distinct from the cumulative `set_order`, which folds
    /// that rank into the running `next_set_order` cursor
    /// (`stored = next_set_order + delta.set_order`, SDD §9.1.5a).
    ///
    /// Oracle: because `apply_set_field` overwrites the field entry
    /// unconditionally on every write (no set_order comparison — LWW by
    /// application order), the authoring value persisted for a surviving
    /// field is exactly the `set_order` of the LAST successfully-applied
    /// `SetField` delta targeting that key. We track that per key and, after
    /// replaying the whole sequence, assert it against every field still
    /// present in `state.fields`. Fields removed by an intervening
    /// section delete simply aren't in `state.fields`, so they're skipped.
    ///
    /// Contrast invariant: the persisted authoring value must equal the raw
    /// delta rank we generated, NOT the cumulative `set_order` and NOT
    /// `next_set_order`. We assert `authoring_set_order == oracle[key]`
    /// (the raw delta value) and, whenever the two genuinely differ,
    /// additionally pin that `authoring_set_order != field.set_order` — proof
    /// the field carries the authoring rank independently of the cursor.
    #[test]
    fn proptest_authoring_set_order_equals_last_writing_delta_set_order(
        cmds in arb_cmd_sequence(),
    ) {
        let mut state = make_state();
        // Oracle: last successfully-applied SetField's raw set_order per key.
        let mut last_write: HashMap<(u64, String), u64> = HashMap::new();

        for cmd in &cmds {
            // Only a rolled-back (tolerated-rejection) delta must not update
            // the oracle; a committed delta does. CreateSection/DeleteSection
            // deltas carry no set_fields, so only the SetField arm records.
            let applied = apply_delta_tolerant(&mut state, cmd_to_delta(cmd))
                .expect("apply_delta must not error on valid delta")
                .is_some();
            if applied {
                if let PropCmd::SetField { section_id, key, set_order, .. } = cmd {
                    last_write.insert((*section_id, key.clone()), *set_order);
                }
            }
        }

        for ((section_id, key_name), field) in &state.fields {
            let expected = last_write.get(&(*section_id, key_name.clone())).copied();
            prop_assert_eq!(
                Some(field.authoring_set_order),
                expected,
                "surviving field ({}, {:?}) has authoring_set_order {} but the last \
                 writing delta's set_order was {:?}",
                section_id, key_name, field.authoring_set_order, expected
            );

            // Independence from the cumulative cursor: the persisted value is
            // the raw delta rank, never `next_set_order`-derived. Since
            // `set_order = next_set_order_at_write + authoring`, the cumulative
            // value is always >= the authoring rank and diverges from it once
            // the cursor has advanced past 0 — pinning that the authoring field
            // is NOT just an alias of the cumulative set_order.
            prop_assert!(
                field.set_order >= field.authoring_set_order,
                "cumulative set_order {} must be >= raw authoring rank {} \
                 (cumulative = next_set_order_at_write + authoring)",
                field.set_order, field.authoring_set_order
            );
        }
    }
}

proptest! {
    #![proptest_config(proptest_config(256))]

    #[test]
    fn proptest_children_lists_sorted_after_every_delta(
        cmds in arb_cmd_sequence(),
    ) {
        let mut state = make_state();
        for cmd in &cmds {
            apply_delta_tolerant(&mut state, cmd_to_delta(cmd)).unwrap();
            for (parent_id, children) in &state.children {
                let orders: Vec<u32> = children
                    .iter()
                    .map(|&cid| state.sections.get(&cid).map(|s| s.section_order).unwrap_or(0))
                    .collect();
                let mut expected = orders.clone();
                expected.sort_unstable();
                prop_assert!(
                    orders == expected,
                    "children of parent {} must be sorted by sectionOrder: {:?} vs {:?}",
                    parent_id, orders, expected
                );
            }
        }
    }
}

proptest! {
    #![proptest_config(proptest_config(256))]

    #[test]
    fn proptest_tombstoned_sections_absent_from_live_state(
        cmds in arb_cmd_sequence(),
    ) {
        let mut state = make_state();

        for cmd in &cmds {
            let Some(mutations) = apply_delta_tolerant(&mut state, cmd_to_delta(cmd)).unwrap()
            else {
                continue;
            };

            let tombstoned_this_delta: Vec<u64> = mutations
                .iter()
                .filter_map(|m| {
                    if let StorageMutation::CreateTombstone { section_id, .. } = m {
                        Some(*section_id)
                    } else {
                        None
                    }
                })
                .collect();

            for sid in &tombstoned_this_delta {
                prop_assert!(
                    !state.sections.contains_key(sid),
                    "section {} was tombstoned in this delta but is still in live state",
                    sid
                );
            }
        }
    }
}

proptest! {
    #![proptest_config(proptest_config(256))]

    #[test]
    fn proptest_children_sort_invariant_full_sequence(
        cmds in arb_cmd_sequence(),
    ) {
        let mut state = make_state();
        apply_prop_cmds(&mut state, &cmds);
        for (parent_id, children) in &state.children {
            let orders: Vec<u32> = children
                .iter()
                .map(|&cid| {
                    state
                        .sections
                        .get(&cid)
                        .map(|s| s.section_order)
                        .unwrap_or(0)
                })
                .collect();
            let mut sorted = orders.clone();
            sorted.sort_unstable();
            assert_eq!(
                orders, sorted,
                "children of parent {parent_id} must be sorted by sectionOrder ascending"
            );
        }
    }
}

// ── b.55p proptests: sequence_num, reset, mutation-type, cross-map ───────────
//
// Four invariants, one for each of the bulleted proptest items in the b.55p
// ticket. Each lives in its own proptest! block so failure shrinking reports
// a minimal counterexample per invariant rather than a noisy aggregate.

proptest! {
    #![proptest_config(proptest_config(256))]

    /// For every successful `apply_delta` call, `state.sequence_num`
    /// increments by exactly 1 (SDD §8.4). A rejected delta leaves state
    /// unchanged (the tolerant helper rolls back). The test rejects
    /// sequence overflow statistically — the starting state is 0 and
    /// `u64::MAX` steps are out of reach.
    #[test]
    fn proptest_apply_delta_success_increments_sequence_by_one(
        cmds in arb_cmd_sequence(),
    ) {
        let mut state = make_state();
        for cmd in &cmds {
            let prev = state.sequence_num;
            if apply_delta_tolerant(&mut state, cmd_to_delta(cmd)).unwrap().is_none() {
                // Rolled back — no increment.
                prop_assert_eq!(state.sequence_num, prev);
                continue;
            }
            prop_assert_eq!(
                state.sequence_num,
                prev + 1,
                "sequence_num must step by exactly 1 on each successful apply"
            );
        }
    }
}

proptest! {
    #![proptest_config(proptest_config(256))]

    /// After applying an arbitrary command sequence, applying a reset delta
    /// (is_diff=true + empty content) must leave `sections`, `fields`, and
    /// `time_samples` empty. SDD §9.1.3.
    #[test]
    fn proptest_reset_empties_state_maps(
        cmds in arb_cmd_sequence(),
    ) {
        let mut state = make_state();
        apply_prop_cmds(&mut state, &cmds);

        // Reset delta: is_diff=false but zero content? Actually, per SDD
        // §9.1.3 the reset signal is is_diff=true with zero content. Mirror
        // the existing inline reset test in delta.rs.
        let reset = OwnedDelta {
            is_diff: true,
            base_version: 0,
            source_format: "usda".to_string(),
            ..Default::default()
        };
        apply_delta(&mut state, Some(reset)).expect("reset must succeed");

        prop_assert!(
            state.sections.is_empty(),
            "reset must empty state.sections, got {} entries",
            state.sections.len()
        );
        prop_assert!(
            state.fields.is_empty(),
            "reset must empty state.fields, got {} entries",
            state.fields.len()
        );
        prop_assert!(
            state.time_samples.is_empty(),
            "reset must empty state.time_samples, got {} entries",
            state.time_samples.len()
        );
    }
}

proptest! {
    #![proptest_config(proptest_config(256))]

    /// Every emitted mutation's kind must match the command that produced it:
    /// - CreateSection / DeleteSection produce only section/tombstone/children/field/time-sample
    ///   mutations (never SetField for an unrelated section or a standalone field mutation).
    /// - SetField produces only SetField + SetObjectHeader (and only for the
    ///   targeted (section_id, key_name) pair).
    ///
    /// The loose check below verifies that a `SetField` command never emits
    /// a `DeleteSection` or `CreateTombstone` mutation, and vice versa — the
    /// minimal cross-variant guard the ticket calls out.
    #[test]
    fn proptest_mutation_variants_match_command_type(
        cmds in arb_cmd_sequence(),
    ) {
        let mut state = make_state();
        for cmd in &cmds {
            let Some(mutations) = apply_delta_tolerant(&mut state, cmd_to_delta(cmd)).unwrap()
            else {
                continue;
            };
            match cmd {
                PropCmd::SetField { .. } => {
                    for m in &mutations {
                        prop_assert!(
                            !matches!(
                                m,
                                StorageMutation::DeleteSection { .. }
                                    | StorageMutation::CreateTombstone { .. }
                                    | StorageMutation::DeleteChildrenList { .. }
                            ),
                            "SetField must not emit section-lifecycle mutations, got {m:?}"
                        );
                    }
                }
                PropCmd::DeleteSection { .. } => {
                    for m in &mutations {
                        prop_assert!(
                            !matches!(m, StorageMutation::SetField { .. }),
                            "DeleteSection must not emit SetField mutations, got {m:?}"
                        );
                    }
                }
                PropCmd::CreateSection { .. } => {
                    // CreateSection can legitimately emit DeleteField / tombstone
                    // mutations when it cascades a conflicting sibling. The
                    // invariant we can assert is: it must not emit a SetField
                    // mutation for a key we never created.
                    for m in &mutations {
                        prop_assert!(
                            !matches!(m, StorageMutation::SetField { .. }),
                            "CreateSection must not emit SetField mutations, got {m:?}"
                        );
                    }
                }
            }
        }
    }
}

proptest! {
    #![proptest_config(proptest_config(256))]

    /// Cross-map consistency (b.55p core invariant): after every successful
    /// `apply_delta`, every child listed in `state.children[parent_id]` must
    /// also exist as a section in `state.sections`, and every list's parent
    /// must be the root or a section with a row — no list is kept under a
    /// missing parent (SDD §10.4). These are the invariants H-dom-2 closed
    /// (reorder ghost) and b.a4k added, which `debug_assert_cross_map_consistent`
    /// guards in debug builds.
    ///
    /// The test exercises the invariant at the proptest level so any future
    /// mutator that introduces ghost ids is caught on a shrunk counterexample
    /// rather than needing a targeted regression.
    #[test]
    fn proptest_children_are_always_real_sections_for_real_parents(
        cmds in arb_cmd_sequence(),
    ) {
        let mut state = make_state();
        apply_prop_cmds(&mut state, &cmds);
        for (&parent_id, children) in &state.children {
            prop_assert!(
                parent_id == 0 || state.sections.contains_key(&parent_id),
                "a children list {children:?} is kept under {parent_id}, which is neither the \
                 root nor a section with a row (b.a4k)"
            );
            for &cid in children {
                prop_assert!(
                    state.sections.contains_key(&cid),
                    "child {cid} of real parent {parent_id} is missing from state.sections \
                     (ghost-id regression — b.55p H-dom-2/3)"
                );
            }
        }
    }
}

// ── b.dmu proptests: cross-map invariants for new error variants ─────────────
//
// Item 8 of the b.dmu ticket calls out proptest coverage for three specific
// rungs that the b.55p proptest harness above doesn't reach:
//
// 1. `apply_diff_change_section` rename-onto-occupied-slot — pin
//    `DuplicateSiblingName` as the deterministic rejection on any state
//    where two sections legitimately share a `(parent_id, name)` slot after
//    a rename would commit.
//
// 2. Self-parenting (CreateSection / DiffChangeSection / MoveSection's
//    new_parent_id and old_parent_id branches) — pin that every
//    parent_id == section_id shape rejects with `DeltaError::SelfParenting`
//    regardless of how the state was constructed. b.39x added the validator
//    arms; b.dmu's contribution is the cross-map invariant proof that no
//    construction path slips past.
//
// 3. ReorderChildren duplicate-id — b.dmu pinned that a repeated id
//    rejected with `DuplicateInReorder`; since b.xje a reorder never rejects
//    and a repeated id counts at its first occurrence (OpenUSD's
//    `SdfApplyListOrdering`), so the pin is now that such a reorder commits,
//    storing each id once, in the order the R6 reference gives. A reorder
//    list with all-unique ids still commits as it always did.
//
// Each invariant is its own proptest! block so failure shrinking reports a
// minimal counterexample per invariant rather than a noisy aggregate.

use oodf_ffi::{CommandDiffChangeSection, CommandMoveSection, CommandReorderChildren};

fn arb_section_name_dmu() -> impl Strategy<Value = String> {
    "[a-z]{1,3}"
}

proptest! {
    #![proptest_config(proptest_config(256))]

    /// b.dmu item 2: a `DiffChangeSection` rename whose `(parent_id, name)`
    /// destination is occupied by a different sibling MUST reject with
    /// `DuplicateSiblingName`. Build a parent with two real siblings A and B,
    /// then rename B to A's name — the validator's pre-mutation conflict
    /// check fires on every shrunk counterexample.
    ///
    /// The proptest seeds an arbitrary occupied parent (0 = root, or a
    /// non-zero parent that we pre-populate) and arbitrary names for the two
    /// siblings. The only constraint is that the two names DIFFER on setup
    /// (the test renames one onto the other, so a pre-collision would
    /// short-circuit). Empty-name renames are excluded by the name
    /// generator's `[a-z]{1,3}` shape.
    #[test]
    fn proptest_dmu_diff_change_section_rename_onto_occupied_slot_rejects(
        name_a in arb_section_name_dmu(),
        name_b in arb_section_name_dmu(),
        parent_id in prop_oneof![Just(0u64), 50u64..60u64],
    ) {
        // Skip cases where the two names happen to collide on setup —
        // there's no "rename onto occupied slot" if they're already the
        // same name (the conflict already exists pre-rename).
        if name_a == name_b {
            return Ok(());
        }

        let mut state = make_state();
        // If parent is non-root, seed it under the synthetic root.
        if parent_id != 0 {
            state.sections.insert(
                parent_id,
                live_edit::domain::types::Section {
                    section_id: parent_id,
                    parent_id: 0,
                    name: "ParentForTest".to_string(),
                    section_type: 0,
                    section_order: 0,
                    first_version: 1,
                    last_version: 1,
                },
            );
            state.children.insert(0, vec![parent_id]);
        }
        // Two siblings under that parent: 100 named name_a, 101 named name_b.
        state.sections.insert(
            100,
            live_edit::domain::types::Section {
                section_id: 100,
                parent_id,
                name: name_a.clone(),
                section_type: 0,
                section_order: 0,
                first_version: 1,
                last_version: 1,
            },
        );
        state.sections.insert(
            101,
            live_edit::domain::types::Section {
                section_id: 101,
                parent_id,
                name: name_b.clone(),
                section_type: 0,
                section_order: 0,
                first_version: 1,
                last_version: 1,
            },
        );
        state.children.entry(parent_id).or_default().extend([100u64, 101]);

        // Rename 101 to name_a — must collide with 100 and reject.
        let pre_seq = state.sequence_num;
        let rename = OwnedDelta {
            is_diff: true,
            base_version: 1,
            struct_commands: vec![StructCommand::DiffChangeSection(CommandDiffChangeSection {
                parent_id,
                section_id: 101,
                section_name: name_a.clone(),
                section_type: 0,
                section_order: 0,
            })],
            ..Default::default()
        };
        let err = apply_delta(&mut state, Some(rename)).unwrap_err();
        prop_assert!(
            matches!(
                err,
                DeltaError::DuplicateSiblingName {
                    section_id: 101,
                    conflicting_id: 100,
                    ..
                }
            ),
            "expected DuplicateSiblingName, got {err:?}"
        );
        // Item 6 contract: sequence_num must not advance on rejection.
        prop_assert_eq!(
            state.sequence_num,
            pre_seq,
            "sequence_num must not advance on DuplicateSiblingName"
        );
    }
}

proptest! {
    #![proptest_config(proptest_config(256))]

    /// b.dmu item 1 + 8: every self-parenting shape (CreateSection,
    /// DiffChangeSection, MoveSection.new_parent_id, MoveSection.old_parent_id)
    /// MUST reject with `SelfParenting` regardless of how the rest of the
    /// state is shaped. The b.39x validator arms are the load-bearing rungs;
    /// this proptest pins that no `(parent_id, section_id)` pair with
    /// `parent_id == section_id && parent_id != 0` escapes any of the four
    /// rejection sites.
    #[test]
    fn proptest_dmu_self_parenting_rejected_on_every_struct_command(
        sid in 1u64..=1_000u64,
        name in arb_section_name_dmu(),
        command_kind in 0u8..4u8,
    ) {
        let mut state = make_state();
        // For MoveSection variants we need the section to exist first.
        state.sections.insert(
            sid,
            live_edit::domain::types::Section {
                section_id: sid,
                parent_id: 0,
                name: "Existing".to_string(),
                section_type: 0,
                section_order: 0,
                first_version: 1,
                last_version: 1,
            },
        );
        state.children.insert(0, vec![sid]);
        let pre_seq = state.sequence_num;

        let delta = match command_kind {
            0 => OwnedDelta {
                // CreateSection with parent_id == section_id.
                is_diff: false,
                struct_commands: vec![StructCommand::CreateSection(CommandCreateSection {
                    parent_id: sid,
                    section_id: sid,
                    section_name: name.clone(),
                    section_type: 0,
                })],
                ..Default::default()
            },
            1 => OwnedDelta {
                // DiffChangeSection with parent_id == section_id.
                is_diff: true,
                base_version: 1,
                struct_commands: vec![StructCommand::DiffChangeSection(CommandDiffChangeSection {
                    parent_id: sid,
                    section_id: sid,
                    section_name: name.clone(),
                    section_type: 0,
                    section_order: 0,
                })],
                ..Default::default()
            },
            2 => OwnedDelta {
                // MoveSection.new_parent_id == section_id (b.39x).
                is_diff: false,
                struct_commands: vec![StructCommand::MoveSection(CommandMoveSection {
                    section_id: sid,
                    old_parent_id: 0,
                    new_parent_id: sid,
                    new_name: name.clone(),
                })],
                ..Default::default()
            },
            _ => OwnedDelta {
                // MoveSection.old_parent_id == section_id (b.39x PM follow-up).
                is_diff: false,
                struct_commands: vec![StructCommand::MoveSection(CommandMoveSection {
                    section_id: sid,
                    old_parent_id: sid,
                    new_parent_id: 12345, // some distinct non-self id
                    new_name: name.clone(),
                })],
                ..Default::default()
            },
        };

        let err = apply_delta(&mut state, Some(delta)).unwrap_err();
        prop_assert!(
            matches!(err, DeltaError::SelfParenting { section_id, .. } if section_id == sid),
            "expected SelfParenting(section_id={sid}), got {err:?}"
        );
        // Item 6 contract: sequence_num must not advance.
        prop_assert_eq!(
            state.sequence_num,
            pre_seq,
            "sequence_num must not advance on SelfParenting"
        );
    }
}

proptest! {
    #![proptest_config(proptest_config(256))]

    /// b.dmu item 4 + 8, as b.xje revised it: a `ReorderChildren` whose
    /// `children_list` names one child twice commits, and the id counts at
    /// its **first** occurrence — the stored list is the R6 reference
    /// [`sdf_apply_list_ordering`] of the children by the list, each id once
    /// (the hazard b.dmu rejected repeats for), keyed `0..K-1` because the
    /// seeded keys all tie.
    ///
    /// The reorder list is the children in order with one of them inserted a
    /// second time at a random position, so whenever that insert lands before
    /// the id's original place, first-occurrence and last-occurrence give
    /// different lists.
    ///
    /// Discriminated by: the engine keeping the last occurrence of a repeat
    /// instead of the first.
    #[test]
    fn proptest_dmu_reorder_children_duplicate_id_commits_at_its_first_occurrence(
        // K real children: 2..=8 to keep counterexamples small.
        n_children in 2u64..=8u64,
        // Which index to duplicate, modulo K.
        dup_idx in 0usize..16,
        // Where in the list to insert the duplicate, modulo K+1.
        insert_idx in 0usize..16,
    ) {
        let mut state = make_state();
        // Parent 5 with `n_children` real children at ids 100..100+n.
        state.sections.insert(
            5,
            live_edit::domain::types::Section {
                section_id: 5,
                parent_id: 0,
                name: "Parent".to_string(),
                section_type: 0,
                section_order: 0,
                first_version: 1,
                last_version: 1,
            },
        );
        state.children.insert(0, vec![5]);
        let mut kids = Vec::new();
        for i in 0..n_children {
            let cid = 100 + i;
            state.sections.insert(
                cid,
                live_edit::domain::types::Section {
                    section_id: cid,
                    parent_id: 5,
                    name: format!("c{cid}"),
                    section_type: 0,
                    section_order: 0,
                    first_version: 1,
                    last_version: 1,
                },
            );
            kids.push(cid);
        }
        state.children.insert(5, kids.clone());

        // Build a reorder list with one id duplicated.
        let n = kids.len();
        let dup_target = kids[dup_idx % n];
        let mut reorder = kids.clone();
        let insert_at = insert_idx % (reorder.len() + 1);
        reorder.insert(insert_at, dup_target);

        let expected = sdf_apply_list_ordering(&kids, &reorder);
        let pre_seq = state.sequence_num;
        let delta = OwnedDelta {
            is_diff: false,
            struct_commands: vec![StructCommand::ReorderChildren(CommandReorderChildren {
                section_id: 5,
                children_list_id: 0,
                children_list: reorder.clone(),
            })],
            ..Default::default()
        };
        let outcome = apply_delta(&mut state, Some(delta));
        prop_assert!(
            outcome.is_ok(),
            "a repeated id must not reject the reorder {:?}: {:?}",
            reorder,
            outcome.err()
        );
        prop_assert_eq!(
            state.sequence_num,
            pre_seq + 1,
            "sequence_num must advance by exactly 1 on commit"
        );
        let stored = state.children.get(&5).cloned().unwrap_or_default();
        prop_assert_eq!(
            &stored,
            &expected,
            "the repeat {} must count at its first occurrence in {:?}",
            dup_target,
            reorder
        );
        let keys: Vec<u32> = stored
            .iter()
            .map(|cid| state.sections[cid].section_order)
            .collect();
        prop_assert_eq!(
            keys,
            (0..n_children as u32).collect::<Vec<_>>(),
            "tied keys are re-keyed 0..K-1 in list order"
        );
    }
}

proptest! {
    #![proptest_config(proptest_config(256))]

    /// Companion to the repeated-id proptest above — a reorder list of every
    /// child, each once, MUST commit and install exactly that list. b.dmu
    /// wrote it as the counter-invariant of its dedup rejection (only
    /// duplicates rejected, no false positives); with no rejection left it
    /// pins that a complete list installs as sent.
    #[test]
    fn proptest_dmu_reorder_children_unique_list_still_commits(
        n_children in 2u64..=8u64,
        rotate_by in 1usize..16,
    ) {
        let mut state = make_state();
        state.sections.insert(
            5,
            live_edit::domain::types::Section {
                section_id: 5,
                parent_id: 0,
                name: "Parent".to_string(),
                section_type: 0,
                section_order: 0,
                first_version: 1,
                last_version: 1,
            },
        );
        state.children.insert(0, vec![5]);
        let mut kids = Vec::new();
        for i in 0..n_children {
            let cid = 200 + i;
            state.sections.insert(
                cid,
                live_edit::domain::types::Section {
                    section_id: cid,
                    parent_id: 5,
                    name: format!("c{cid}"),
                    section_type: 0,
                    section_order: 0,
                    first_version: 1,
                    last_version: 1,
                },
            );
            kids.push(cid);
        }
        state.children.insert(5, kids.clone());

        // Rotate the children list by `rotate_by` modulo K to get a
        // distinct-but-unique reorder list.
        let n = kids.len();
        let rot = rotate_by % n;
        let mut reorder = kids.clone();
        reorder.rotate_left(rot);

        let pre_seq = state.sequence_num;
        let delta = OwnedDelta {
            is_diff: false,
            struct_commands: vec![StructCommand::ReorderChildren(CommandReorderChildren {
                section_id: 5,
                children_list_id: 0,
                children_list: reorder.clone(),
            })],
            ..Default::default()
        };
        apply_delta(&mut state, Some(delta)).expect("unique reorder must commit");
        prop_assert_eq!(
            state.children.get(&5).cloned().unwrap_or_default(),
            reorder,
            "children list must reflect the reorder after commit"
        );
        prop_assert_eq!(
            state.sequence_num,
            pre_seq + 1,
            "sequence_num must advance by exactly 1 on commit"
        );
    }
}

// ── OMPF property-based tests ────────────────────────────────────────────────

proptest! {
    #![proptest_config(proptest_config(256))]

    #[test]
    fn proptest_serialize_parse_identity(
        delta in prop::collection::vec(any::<u8>(), 0..1024),
        external_values in prop::collection::vec(
            prop::collection::vec(any::<u8>(), 0..256),
            0..8,
        ),
    ) {
        let ext_slices: Vec<&[u8]> = external_values.iter().map(|v| v.as_slice()).collect();
        let serialized = OmpfContainer::serialize(&delta, &ext_slices).unwrap();
        if serialized.is_empty() {
            let c = OmpfContainer::parse(&serialized).unwrap();
            prop_assert!(c.delta_bytes.is_empty());
            prop_assert!(c.external_values.is_empty());
        } else {
            let parsed = OmpfContainer::parse(&serialized).unwrap();
            prop_assert_eq!(parsed.delta_bytes, delta.as_slice());
            prop_assert_eq!(parsed.external_values.len(), external_values.len());
            for (i, ext) in external_values.iter().enumerate() {
                prop_assert_eq!(parsed.external_values[i], ext.as_slice());
            }
        }
    }
}

proptest! {
    #![proptest_config(proptest_config(512))]

    #[test]
    fn proptest_random_bytes_never_panic(
        data in prop::collection::vec(any::<u8>(), 0..4096),
    ) {
        let _ = OmpfContainer::parse(&data);
    }
}

